// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    ReceiverMock r;

    function setUp() public { 
        c = new AirDropContract();
        r = new ReceiverMock();
    }

    // fuzz the array length and a single value; the fuzzer will populate dynamic arrays
    function testFuzz_property(address target, uint256 v, uint256 len) public {
        // admissible conditions: target must be non-zero and not c itself (modifier in C enforces that)
        // ensure len is reasonable to avoid OOG in fuzz harness
        len = bound(len, 1, 10);

        // build arrays for tos and vs
        address[] memory tos = new address[](len);
        uint[] memory vs = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(r); // route all calls to our recording receiver so calls succeed and are observed
            vs[i] = v;
        }

        // Call c.transfer via try/catch to observe whether it returns (successful) and capture the return value
        bool ok = false;
        bool ret = false;
        try c.transfer(address(r), tos, vs) returns (bool b) {
            ok = true;
            ret = b;
        } catch {
            ok = false;
        }

        // General rule: when transfer completes (ok==true), reference returns true for all inputs.
        // The mutant changes final return to false; this assert will fail on the mutant for some inputs.
        if (ok) {
            assertTrue(ret == true);
        } else {
            // if call reverted, nothing to assert about return value; still passing for this input
            assertTrue(true);
        }
    }
}

// Recording receiver that exposes the transferFrom signature so C's low-level call decodes into it.
contract ReceiverMock {
    // simple storage to record last call attributes (not strictly required for this property but allowed)
    address public lastFrom;
    address public lastTo;
    uint public lastValue;
    uint public calls;

    // match transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        calls += 1;
        return true; // succeed so C's require(_s) passes
    }

    // receive fallback to accept plain ETH if needed
    receive() external payable {}
}
